mapper.select:
select category_seq, parent_seq, name from tbl_category where enabled = 'Y'
and parent_seq is null and parent_seq = #{parentSeq}
order by sort_order, category_seq

select r.request_seq, r.expert_seq, r.category_seq, c.name as category_name, m.name as expert_name, r.address, r.status, r.hidden, r.quote_count, to_char(r.quote_deadline, 'YYYY-MM-DD HH24:MI') as quote_deadline, to_char(r.regdate, 'YYYY-MM-DD') as regdate from tbl_request r join tbl_category c on c.category_seq = r.category_seq left join tbl_member m on m.member_seq = r.expert_seq where r.customer_seq = #{customerSeq}
and r.status = #{status}
order by r.request_seq desc

mapper.update:
update tbl_request
	set status = 'CANCELED'
		where request_seq = #{requestSeq}
			and customer_seq = #{customerSeq}
			and status in ('OPEN', 'CLOSED')
